INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('taohuayuan-ji', NULL, NULL, '桃花源記', '陶淵明', '東晉', '文言文', 2, '[{"id":"P1","text":"晉太元中，武陵人捕魚為業。緣溪行，忘路之遠近。忽逢桃花林，夾岸數百步，中無雜樹，芳草鮮美，落英繽紛。漁人甚異之。復前行，欲窮其林。"},{"id":"P2","text":"林盡水源，便得一山，山有小口，彷彿若有光。便舍船，從口入。初極狹，纔通人。復行數十步，豁然開朗。土地平曠，屋舍儼然，有良田美池桑竹之屬。阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人。黃髮垂髫，並怡然自樂。"},{"id":"P3","text":"見漁人，乃大驚，問所從來。具答之。便要還家，設酒殺雞作食。村中聞有此人，咸來問訊。自云先世避秦時亂，率妻子邑人來此絕境，不復出焉，遂與外人間隔。問今是何世，乃不知有漢，無論魏晉。此人一一為具言所聞，皆歎惋。餘人各復延至其家，皆出酒食。停數日，辭去。此中人語云：「不足為外人道也。」"},{"id":"P4","text":"既出，得其船，便扶向路，處處誌之。及郡下，詣太守，說如此。太守即遣人隨其往，尋向所誌，遂迷，不復得路。"},{"id":"P5","text":"南陽劉子驥，高尚士也，聞之，欣然規往。未果，尋病終。後遂無問津者。"}]', 320, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('ailian-shuo', NULL, NULL, '愛蓮說', '周敦頤', '北宋', '文言文', 1, '[{"id":"P1","text":"水陸草木之花，可愛者甚蕃。晉陶淵明獨愛菊。自李唐來，世人甚愛牡丹。予獨愛蓮之出淤泥而不染，濯清漣而不妖，中通外直，不蔓不枝，香遠益清，亭亭淨植，可遠觀而不可褻玩焉。"},{"id":"P2","text":"予謂菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也。噫！菊之愛，陶後鮮有聞。蓮之愛，同予者何人？牡丹之愛，宜乎眾矣。"}]', 119, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('zuiweng-ting-ji', NULL, NULL, '醉翁亭記', '歐陽脩', '北宋', '文言文', 3, '[{"id":"P1","text":"環滁皆山也。其西南諸峰，林壑尤美，望之蔚然而深秀者，琅琊也。山行六七里，漸聞水聲潺潺，而瀉出於兩峰之間者，釀泉也。峰迴路轉，有亭翼然臨於泉上者，醉翁亭也。作亭者誰？山之僧智僊也。名之者誰？太守自謂也。太守與客來飲於此，飲少輒醉，而年又最高，故自號曰醉翁也。醉翁之意不在酒，在乎山水之間也。山水之樂，得之心而寓之酒也。"},{"id":"P2","text":"若夫日出而林霏開，雲歸而巖穴暝，晦明變化者，山間之朝暮也。野芳發而幽香，佳木秀而繁陰，風霜高潔，水落而石出者，山間之四時也。朝而往，暮而歸，四時之景不同，而樂亦無窮也。"},{"id":"P3","text":"至於負者歌於塗，行者休於樹，前者呼，後者應，傴僂提攜，往來而不絕者，滁人遊也。臨溪而漁，溪深而魚肥；釀泉為酒，泉香而酒洌；山肴野蔌，雜然而前陳者，太守宴也。宴酣之樂，非絲非竹，射者中，弈者勝，觥籌交錯，起坐而諠譁者，眾賓懽也。蒼顏白髮，頹然乎其間者，太守醉也。"},{"id":"P4","text":"已而夕陽在山，人影散亂，太守歸而賓客從也。樹林陰翳，鳴聲上下，遊人去而禽鳥樂也。然而禽鳥知山林之樂，而不知人之樂；人知從太守遊而樂，而不知太守之樂其樂也。醉能同其樂，醒能述以文者，太守也。太守謂誰？廬陵歐陽脩也。"}]', 402, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('yueyang-lou-ji', NULL, NULL, '岳陽樓記', '范仲淹', '北宋', '文言文', 4, '[{"id":"P1","text":"慶曆四年春，滕子京謫守巴陵郡。越明年，政通人和，百廢具興。乃重修岳陽樓，增其舊制，刻唐賢今人詩賦於其上。屬予作文以記之。"},{"id":"P2","text":"予觀夫巴陵勝狀，在洞庭一湖。銜遠山，吞長江，浩浩湯湯，橫無際涯；朝暉夕陰，氣象萬千。此則岳陽樓之大觀也，前人之述備矣。然則北通巫峽，南極瀟湘，遷客騷人，多會於此，覽物之情，得無異乎？"},{"id":"P3","text":"若夫霪雨霏霏，連月不開；陰風怒號，濁浪排空；日星隱曜，山岳潛形；商旅不行，檣傾楫摧；薄暮冥冥，虎嘯猿啼。登斯樓也，則有去國懷鄉，憂讒畏譏，滿目蕭然，感極而悲者矣。"},{"id":"P4","text":"至若春和景明，波瀾不驚，上下天光，一碧萬頃；沙鷗翔集，錦鱗游泳；岸芷汀蘭，郁郁青青。而或長煙一空，皓月千里，浮光躍金，靜影沉璧；漁歌互答，此樂何極！登斯樓也，則有心曠神怡，寵辱偕忘，把酒臨風，其喜洋洋者矣。"},{"id":"P5","text":"嗟夫！予嘗求古仁人之心，或異二者之為，何哉？不以物喜，不以己悲；居廟堂之高，則憂其民；處江湖之遠，則憂其君。是進亦憂，退亦憂；然則何時而樂耶？其必曰：「先天下之憂而憂，後天下之樂而樂」歟！噫！微斯人，吾誰與歸？"},{"id":"P6","text":"時六年九月十五日。"}]', 368, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('shi-shuo', NULL, NULL, '師說', '韓愈', '唐', '文言文', 4, '[{"id":"P1","text":"古之學者必有師。師者，所以傳道、受業、解惑也。人非生而知之者，孰能無惑？惑而不從師，其為惑也，終不解矣。生乎吾前，其聞道也固先乎吾，吾從而師之；生乎吾後，其聞道也亦先乎吾，吾從而師之。吾師道也，夫庸知其年之先後生於吾乎？是故無貴無賤，無長無少，道之所存，師之所存也。"},{"id":"P2","text":"嗟乎！師道之不傳也久矣！欲人之無惑也難矣！古之聖人，其出人也遠矣，猶且從師而問焉；今之眾人，其下聖人也亦遠矣，而恥學於師。是故聖益聖，愚益愚。聖人之所以為聖，愚人之所以為愚，其皆出於此乎？愛其子，擇師而教之；於其身也，則恥師焉，惑矣。彼童子之師，授之書而習其句讀者，非吾所謂傳其道、解其惑者也。句讀之不知，惑之不解，或師焉，或不焉，小學而大遺，吾未見其明也。巫醫、樂師、百工之人，不恥相師；士大夫之族，曰師、曰弟子云者，則群聚而笑之。問之，則曰：「彼與彼年相若也，道相似也。位卑則足羞，官盛則近諛。」嗚呼！師道之不復可知矣。巫醫、樂師、百工之人，君子不齒，今其智乃反不能及，其可怪也歟！"},{"id":"P3","text":"聖人無常師。孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子。孔子曰：「三人行，則必有我師。」是故弟子不必不如師，師不必賢於弟子。聞道有先後，術業有專攻，如是而已。"},{"id":"P4","text":"李氏子蟠，年十七，好古文，六藝經傳皆通習之，不拘於時，學於余。余嘉其能行古道，作師說以貽之。"}]', 456, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('chu-shi-biao', NULL, NULL, '出師表', '諸葛亮', '三國蜀漢', '文言文', 4, '[{"id":"P1","text":"臣亮言：先帝創業未半，而中道崩殂。今天下三分，益州疲弊，此誠危急存亡之秋也。然侍衛之臣，不懈於內；忠志之士，忘身於外者，蓋追先帝之殊遇，欲報之於陛下也。誠宜開張聖聽，以光先帝遺德，恢弘志士之氣；不宜妄自菲薄，引喻失義，以塞忠諫之路也。"},{"id":"P2","text":"宮中府中，俱為一體，陟罰臧否，不宜異同。若有作姦犯科，及為忠善者，宜付有司，論其刑賞，以昭陛下平明之治；不宜偏私，使內外異法也。"},{"id":"P3","text":"侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。愚以為宮中之事，事無大小，悉以咨之，然後施行，必能裨補闕漏，有所廣益。"},{"id":"P4","text":"將軍向寵，性行淑均，曉暢軍事，試用於昔日，先帝稱之曰「能」，是以眾議舉寵為督。愚以為營中之事，悉以咨之，必能使行陣和睦，優劣得所。"},{"id":"P5","text":"親賢臣，遠小人，此先漢所以興隆也；親小人，遠賢臣，此後漢所以傾頹也。先帝在時，每與臣論此事，未嘗不歎息痛恨於桓、靈也。侍中、尚書、長史、參軍，此悉貞良死節之臣，願陛下親之信之，則漢室之隆，可計日而待也。"},{"id":"P6","text":"臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯。先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中，諮臣以當世之事，由是感激，遂許先帝以驅馳。後值傾覆，受任於敗軍之際，奉命於危難之間，爾來二十有一年矣。"},{"id":"P7","text":"先帝知臣謹慎，故臨崩寄臣以大事也。受命以來，夙夜憂歎，恐託付不效，以傷先帝之明；故五月渡瀘，深入不毛。今南方已定，兵甲已足，當獎率三軍，北定中原，庶竭駑鈍，攘除姦凶，興復漢室，還於舊都。此臣所以報先帝而忠陛下之職分也。至於斟酌損益，進盡忠言，則攸之、禕、允之任也。"},{"id":"P8","text":"願陛下託臣以討賊興復之效；不效，則治臣之罪，以告先帝之靈。若無興德之言，則責攸之、禕、允等之慢，以彰其咎。陛下亦宜自謀，以諮諏善道，察納雅言，深追先帝遺詔。臣不勝受恩感激。"},{"id":"P9","text":"今當遠離，臨表涕零，不知所言。"}]', 627, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('qian-chibi-fu', NULL, NULL, '赤壁賦', '蘇軾', '北宋', '文言文', 5, '[{"id":"P1","text":"壬戌之秋，七月既望，蘇子與客泛舟，遊於赤壁之下。清風徐來，水波不興。舉酒屬客，誦明月之詩，歌窈窕之章。少焉，月出於東山之上，徘徊於斗牛之間。白露橫江，水光接天。縱一葦之所如，凌萬頃之茫然。浩浩乎如馮虛御風，而不知其所止；飄飄乎如遺世獨立，羽化而登仙。"},{"id":"P2","text":"於是飲酒樂甚，扣舷而歌之。歌曰：「桂棹兮蘭槳，擊空明兮泝流光。渺渺兮予懷，望美人兮天一方。」客有吹洞簫者，倚歌而和之，其聲嗚嗚然，如怨如慕，如泣如訴；餘音嫋嫋，不絕如縷；舞幽壑之潛蛟，泣孤舟之嫠婦。"},{"id":"P3","text":"蘇子愀然，正襟危坐，而問客曰：「何為其然也？」客曰：「『月明星稀，烏鵲南飛』，此非曹孟德之詩乎？西望夏口，東望武昌，山川相繆，鬱乎蒼蒼，此非孟德之困於周郎者乎？方其破荊州，下江陵，順流而東也，舳艫千里，旌旗蔽空，釃酒臨江，橫槊賦詩，固一世之雄也，而今安在哉？況吾與子漁樵於江渚之上，侶魚蝦而友麋鹿，駕一葉之扁舟，舉匏樽以相屬；寄蜉蝣於天地，渺滄海之一粟。哀吾生之須臾，羨長江之無窮；挾飛仙以遨遊，抱明月而長終；知不可乎驟得，託遺響於悲風。」"},{"id":"P4","text":"蘇子曰：「客亦知夫水與月乎？逝者如斯，而未嘗往也；盈虛者如彼，而卒莫消長也。蓋將自其變者而觀之，則天地曾不能以一瞬；自其不變者而觀之，則物與我皆無盡也，而又何羨乎？且夫天地之間，物各有主，苟非吾之所有，雖一毫而莫取。惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色，取之無禁，用之不竭，是造物者之無盡藏也，而吾與子之所共適。」"},{"id":"P5","text":"客喜而笑，洗盞更酌。肴核既盡，杯盤狼籍。相與枕藉乎舟中，不知東方之既白。"}]', 537, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('congcong', NULL, NULL, '匆匆', '朱自清', '民國（1922）', '散文', 1, '[{"id":"P1","text":"燕子去了，有再來的時候；楊柳枯了，有再青的時候；桃花謝了，有再開的時候。但是，聰明的，你告訴我，我們的日子為什麼一去不復返呢？——是有人偷了他們罷：那是誰？又藏在何處呢？是他們自己逃走了罷：現在又到了那裡呢？"},{"id":"P2","text":"我不知道他們給了我多少日子；但我的手確乎是漸漸空虛了。在默默裡算著，八千多日子已經從我手中溜去；像針尖上一滴水滴在大海裡，我的日子滴在時間的流裡，沒有聲音，也沒有影子。我不禁頭涔涔而淚潸潸了。"},{"id":"P3","text":"去的儘管去了，來的儘管來著；去來的中間，又怎樣地匆匆呢？早上我起來的時候，小屋裡射進兩三方斜斜的太陽。太陽他有腳啊，輕輕悄悄地挪移了；我也茫茫然跟著旋轉。於是——洗手的時候，日子從水盆裡過去；吃飯的時候，日子從飯碗裡過去；默默時，便從凝然的雙眼前過去。我覺察他去的匆匆了，伸出手遮挽時，他又從遮挽著的手邊過去，天黑時，我躺在床上，他便伶伶俐俐地從我身上跨過，從我腳邊飛去了。等我睜開眼和太陽再見，這算又溜走了一日。我掩著面歎息。但是新來的日子的影兒又開始在歎息裡閃過了。"},{"id":"P4","text":"在逃去如飛的日子裡，在千門萬戶的世界裡的我能做些什麼呢？只有徘徊罷了，只有匆匆罷了；在八千多日的匆匆裡，除徘徊外，又剩些什麼呢？過去的日子如輕煙，被微風吹散了，如薄霧，被初陽蒸融了；我留著些什麼痕跡呢？我何曾留著像游絲樣的痕跡呢？我赤裸裸來到這世界，轉眼間也將赤裸裸的回去罷？但不能平的，為什麼偏要白白走這一遭啊？"},{"id":"P5","text":"你聰明的，告訴我，我們的日子為什麼一去不復返呢？"}]', 542, 'public-domain');
INSERT OR REPLACE INTO articles (id, source_id, url, title, author, era, genre, difficulty, paragraphs_json, char_count, license) VALUES ('luo-huasheng', NULL, NULL, '落花生', '許地山', '民國（1922）', '記敘文', 1, '[{"id":"P1","text":"我們屋後有半畝隙地。母親說：「讓它荒蕪著怪可惜，既然你們那麼愛吃花生，就闢來做花生園罷。」我們幾姊弟和幾個小丫頭都很喜歡——買種的買種，動土的動土，灌園的灌園；過不了幾個月，居然收穫了！"},{"id":"P2","text":"媽媽說：「今晚我們可以做一個收穫節，也請你們爹爹來嘗嘗我們的新花生，如何？」我們都答應了。母親把花生做成好幾樣的食品，還吩咐這節期要在園裡的茅亭舉行。"},{"id":"P3","text":"那晚上的天色不大好，可是爹爹也到來，實在很難得！爹爹說：「你們愛吃花生麼？」我們都爭著答應：「愛！」「誰能把花生的好處說出來？」姊姊說：「花生的氣味很美。」哥哥說：「花生可以製油。」我說：「無論何等人都可以用賤價買它來吃；都喜歡吃它。這就是它的好處。」"},{"id":"P4","text":"爹爹說：「花生的用處固然很多；但有一樣是很可貴的。這小小的豆不像那好看的蘋果、桃子、石榴，把它們的果實懸在枝上，鮮紅嫩綠的顏色，令人一望而發生羨慕的心。它只把果子埋在地底，等到成熟，才容人把它挖出來。你們偶然看見一棵花生瑟縮地長在地上，不能立刻辨出它有沒有果實，非得等到你接觸它才能知道。」"},{"id":"P5","text":"我們都說：「是的。」母親也點點頭。爹爹接下去說：「所以你們要像花生，因為它是有用的，不是偉大、好看的東西。」我說：「那麼，人要做有用的人，不要做偉大、體面的人了。」爹爹說：「這是我對於你們的希望。」"},{"id":"P6","text":"我們談到夜闌才散，所有花生食品雖然沒有了，然而父親的話現在還印在我心版上。"}]', 481, 'public-domain');
